import{_ as e,o as t,c as d,a2 as r}from"./chunks/framework.XLDuFJDd.js";const p=JSON.parse('{"title":"数据驱动","description":"","frontmatter":{},"headers":[],"relativePath":"guide/data-driven.md","filePath":"guide/data-driven.md"}'),o={name:"guide/data-driven.md"};function m(h,a,c,l,n,s){return t(),d("div",null,[...a[0]||(a[0]=[r('<h1 id="数据驱动" tabindex="-1">数据驱动 <a class="header-anchor" href="#数据驱动" aria-label="Permalink to &quot;数据驱动&quot;">​</a></h1><p>数据源与控件分离：静态控件消费选项；异步控件通过统一数据运行时处理请求、状态与回显。 开始前阅读<a href="/guide/provider.html">数据 provider</a>，明确宿主需要注入的请求和字典能力。</p><h2 id="选择数据来源" tabindex="-1">选择数据来源 <a class="header-anchor" href="#选择数据来源" aria-label="Permalink to &quot;选择数据来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>适用情况</th><th>入口</th></tr></thead><tbody><tr><td>静态选项</td><td>已知选项，无需请求</td><td><a href="/component-AsamSelect.html">AsamSelect</a></td></tr><tr><td>API 函数</td><td>宿主已封装请求</td><td><a href="/component-AsamRemoteSelect.html">AsamRemoteSelect</a></td></tr><tr><td>URL 配置</td><td>由 provider 统一发起请求</td><td><a href="/guide/provider.html">provider 指南</a></td></tr><tr><td>字典</td><td>复用宿主字典能力</td><td><a href="/component-AsamDictSelect.html">AsamDictSelect</a></td></tr></tbody></table><p>同一数据源入口使用一种来源。响应转换与字段映射用于归一化列表；业务接口、认证和 字典持久缓存由宿主负责。数据类型与函数签名从包导出，官网不复制一套字段表。</p><h2 id="请求状态与上下文" tabindex="-1">请求状态与上下文 <a class="header-anchor" href="#请求状态与上下文" aria-label="Permalink to &quot;请求状态与上下文&quot;">​</a></h2><p>区分初始、加载、成功、空结果和失败。首次失败没有成功快照；后续刷新失败保留上次成功 结果，并标明已过期。重试和强制刷新由调用方显式触发，不隐式无限重试。</p><p>宿主传递取消信号，并在登录或租户切换时更新 data scope。scope 只是隔离标识，不应放入 token 或个人数据。默认不启用远程缓存；需要复用时按公开契约明确 TTL 与缓存键。 完整状态场景在 <a href="/component-AsamRemoteSelect.html">AsamRemoteSelect</a> 中使用确定性 Mock 验证。</p><h2 id="表格与表单" tabindex="-1">表格与表单 <a class="header-anchor" href="#表格与表单" aria-label="Permalink to &quot;表格与表单&quot;">​</a></h2><p><code>AsamTable</code> 展示调用方传入的数据；<code>AsamDataTable</code> 处理远程分页请求和选择状态。 示例与分页契约见 <a href="/component-AsamDataTable.html">AsamDataTable</a>。</p><p><code>AsamForm</code> 的旧 fields 与新 schema 不能同时传入。schema 通过显式依赖描述联动，包含 依赖清值、隐藏暂停与失败后的过期快照。泛型字段、插槽、注册表及实际交互见 <a href="/component-AsamForm.html">AsamForm</a>。</p><h2 id="依据与范围" tabindex="-1">依据与范围 <a class="header-anchor" href="#依据与范围" aria-label="Permalink to &quot;依据与范围&quot;">​</a></h2><p>来源为 <code>docs/ASAM_UI_DATA_DRIVEN_DESIGN.md</code> 第 2–8、10 节，以及同源 provider 指南、 AsamDataTable 与 AsamForm Story。全部展示使用合成数据；本地演示不证明真实后端联调已完成。 当前能力、透传和类型提取限制以<a href="/components.html">组件目录</a>所链接的版本为准。</p>',13)])])}const A=e(o,[["render",m]]);export{p as __pageData,A as default};
